    runs=[]
    for r in range(len(g)):
        cs=[c for c in range(len(g[0])) if (r,c) in cells]
        if cs:
            groups=[]; cur=[cs[0]]
            for c in cs[1:]:
                if c==cur[-1]+1: cur.append(c)
                else: groups.append(cur); cur=[c]
            groups.append(cur)
            runs.append((r,groups))
    # rectangles generated by identical column spans in consecutive rows
    rects=[]
    active={}
    for r,groups in runs+[(len(g),[])]:
        spans=[(x[0],x[-1]) for x in groups]
        new={}
        for span in spans:
            if span in active: new[span]=active[span]
            else: new[span]=r
        for span,start in active.items():
            if span not in new: rects.append((start,r-1,span[0],span[1]))
        active=new
    rects.sort()
    # Colored key order by first appearance (top-to-bottom, left-to-right),
    # corresponds to the block order in the 8 figure's schematic layout.
    colors=[]
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v not in (0,8) and v not in colors: colors.append(v)
    # Assign key colors cyclically by rectangle order; demo shows merged adjacent
    # rectangles with same row spans should get same color, while distinct blocks
    # follow the key's color sequence.
    for i,(r1,r2,c1,c2) in enumerate(rects):
        color=colors[i%len(colors)] if colors else 8
        for r in range(r1,r2+1):
            for c in range(c1,c2+1):
                if g[r][c]==8: g[r][c]=color
    return g
